"use strict";exports.type="visitor",exports.name="sortDefsChildren",exports.active=!0,exports.description="Sorts children of <defs> to improve compression",exports.fn=()=>({element:{enter:e=>{if("defs"===e.name){const n=new Map;for(const t of e.children)if("element"===t.type){const e=n.get(t.name);null==e?n.set(t.name,1):n.set(t.name,e+1)}e.children.sort((e,t)=>{if("element"!==e.type||"element"!==t.type)return 0;const r=n.get(e.name),s=n.get(t.name);if(null!=r&&null!=s){const e=s-r;if(0!==e)return e}const o=t.name.length-e.name.length;return 0!==o?o:e.name!==t.name?e.name>t.name?-1:1:0})}}}});